class Solution {
    public int subarraysWithXorK(int[] nums, int k) {
      int cnt=0;
      int xor=0;
      HashMap<Integer, Integer> map = new HashMap<>();
      map.put(0,1);
      for(int i=0; i<nums.length; i++){
        xor = nums[i]^xor;
        int x = xor^k;
        if(map.containsKey(x)){
            int value = map.getOrDefault(x, 0);
            cnt += value;
        }
        map.put(xor, map.getOrDefault(xor, 0)+1);
      }
      return cnt;
    }
}
