class Solution{
public:
    int subarraysWithXorK(vector<int> &nums, int k) {
        int n = nums.size();
        if(n == 0){
            return 0;
        }
        int count = 0;
        vector<int> preXor(n);
        preXor[0] = nums[0];
        for(int i = 1; i < n; i++){
            preXor[i] = preXor[i-1] ^ nums[i];
        }

        unordered_map<int, int> mp;
        for(int i = 0; i < n; i++){
            if(preXor[i] == k){
                count++;
            }
            int need = preXor[i] ^ k;
            if(mp.find(need) != mp.end()){
                count += mp[need];
                mp[preXor[i]]++;
            }
            else{
                mp[preXor[i]]++;
            }
        }
        return count;
    }
};
